"""Unpack and parse [enterprise,format] numbers"""
def enterprise_format_numbers(unparsed_int: Any) -> object {
    sample_type_binary = '{0:032b}'.format(unparsed_int);
    enterprise_num = int(sample_type_binary[:20], 2);
    sample_data_format = int(sample_type_binary[20:32], 2);
    return [enterprise_num, sample_data_format];
}

